package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {



























    @Test
    public void testCreateNumber_InvalidExponentPosition() {
        // expPos < decPos case: "1e.5" -> e is at 1, . is at 2. 
        // The logic: expPos = str.indexOf('e') + str.indexOf('E') + 1.
        // If e is present but E is not, indexOf('E') is -1. 
        // So expPos = 1 + (-1) + 1 = 1. decPos = 2. 1 < 2 is true.
        try {
            NumberUtils.createNumber("1e.5");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            assertTrue(e.getMessage().contains("is not a valid number"));
        }
    }










}

